"""Idempotent receipts binding a state to an audit record.

A receipt only names an ``id`` and the two 64-char lowercase hex digests of
the state and audit record it binds; the state and audit bytes themselves
are never read or written here.  Receipts are kept in an index stored as
UTF-8 compact JSON::

    {"items":[{"audit":...,"id":...,"state":...},...],"version":1}\\n

The top-level keys are fixed in the order ``items`` then ``version`` and
``version`` is always the integer 1.  ``items`` is an array of records
sorted ascending by ``id`` (ids are unique); each record carries the str
keys ``id``, ``state`` and ``audit`` and is canonically encoded with the
key order ``audit``, ``id``, ``state``.  Non-ASCII characters are preserved
unescaped and the file ends with exactly one ``\\n``.

A missing index file stands for an empty index; an existing file that
violates any byte, structure, order or field rule is corrupt.
"""

from __future__ import annotations

import json
import os
import re
from typing import Any

AUDIT = "audit"
ID = "id"
STATE = "state"

ITEMS = "items"
VERSION = "version"

_RECEIPT_KEYS = (ID, STATE, AUDIT)
_RECORD_KEYS = (AUDIT, ID, STATE)
_INDEX_KEYS = (ITEMS, VERSION)
_INDEX_VERSION = 1

_ID_RE = re.compile(r"[A-Za-z0-9._-]{1,64}\Z")
_DIGEST_RE = re.compile(r"[0-9a-f]{64}\Z")


class CorruptReceiptError(ValueError):
    """The receipt index exists but its bytes are not a valid index."""


def _is_digest(value: Any) -> bool:
    return isinstance(value, str) and _DIGEST_RE.fullmatch(value) is not None


def _validated_receipt(receipt: Any) -> dict[str, str]:
    """Validate one receipt and return a fresh dict in record key order."""
    if not isinstance(receipt, dict):
        raise TypeError("receipt must be a dict")
    if set(receipt.keys()) != set(_RECEIPT_KEYS):
        raise ValueError(
            "receipt must contain exactly the keys 'id', 'state' and 'audit'"
        )
    for key in _RECEIPT_KEYS:
        if not isinstance(receipt[key], str):
            raise TypeError(f"receipt {key} must be a str")
    receipt_id = receipt[ID]
    if _ID_RE.fullmatch(receipt_id) is None:
        raise ValueError("receipt id must match [A-Za-z0-9._-]{1,64}")
    if not _is_digest(receipt[STATE]):
        raise ValueError("receipt state must be 64 lowercase hex characters")
    if not _is_digest(receipt[AUDIT]):
        raise ValueError("receipt audit must be 64 lowercase hex characters")
    return {AUDIT: receipt[AUDIT], ID: receipt_id, STATE: receipt[STATE]}


def _serialize_index(records: list[dict[str, str]]) -> bytes:
    ordered = [
        {AUDIT: record[AUDIT], ID: record[ID], STATE: record[STATE]}
        for record in records
    ]
    index = {ITEMS: ordered, VERSION: _INDEX_VERSION}
    text = json.dumps(index, ensure_ascii=False, separators=(",", ":")) + "\n"
    return text.encode("utf-8")


def _parse_index(raw: bytes) -> list[dict[str, str]]:
    """Validate every byte of a receipt index and return its records.

    Raises :class:`CorruptReceiptError` for any UTF-8/JSON failure,
    non-canonical byte encoding, wrong key set or order, bad version,
    duplicate or unsorted ids, or a field that is not a well-formed str.
    """
    if raw == b"":
        raise CorruptReceiptError("receipt index is empty")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptReceiptError("receipt index is not valid UTF-8") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise CorruptReceiptError("receipt index is not valid JSON") from exc

    if not isinstance(data, dict):
        raise CorruptReceiptError("receipt index must be a JSON object")
    if set(data.keys()) != set(_INDEX_KEYS):
        raise CorruptReceiptError(
            "receipt index must contain exactly the keys 'items' and 'version'"
        )
    if list(data.keys()) != list(_INDEX_KEYS):
        raise CorruptReceiptError(
            "receipt index keys must be in the order 'items', 'version'"
        )
    version = data[VERSION]
    # bool is a subclass of int; the version must be a genuine integer.
    if isinstance(version, bool) or not isinstance(version, int) or version != 1:
        raise CorruptReceiptError("receipt index version must be the integer 1")
    raw_items = data[ITEMS]
    if not isinstance(raw_items, list):
        raise CorruptReceiptError("receipt index items must be an array")

    records: list[dict[str, str]] = []
    for position, item in enumerate(raw_items):
        where = f"receipt index item {position}"
        if not isinstance(item, dict):
            raise CorruptReceiptError(f"{where} must be a JSON object")
        if set(item.keys()) != set(_RECORD_KEYS):
            raise CorruptReceiptError(
                f"{where} must contain exactly the keys 'audit', 'id' and 'state'"
            )
        if list(item.keys()) != list(_RECORD_KEYS):
            raise CorruptReceiptError(
                f"{where} keys must be in the order 'audit', 'id', 'state'"
            )
        audit_digest = item[AUDIT]
        record_id = item[ID]
        state_digest = item[STATE]
        if not isinstance(record_id, str) or _ID_RE.fullmatch(record_id) is None:
            raise CorruptReceiptError(f"{where} has an invalid id")
        if not _is_digest(state_digest):
            raise CorruptReceiptError(
                f"{where} state must be 64 lowercase hex characters"
            )
        if not _is_digest(audit_digest):
            raise CorruptReceiptError(
                f"{where} audit must be 64 lowercase hex characters"
            )
        records.append(
            {AUDIT: audit_digest, ID: record_id, STATE: state_digest}
        )

    ids = [record[ID] for record in records]
    if any(left >= right for left, right in zip(ids, ids[1:])):
        raise CorruptReceiptError(
            "receipt index ids must be unique and sorted ascending"
        )

    # Reject stray whitespace, non-canonical escapes, and any encoding that
    # is not the single compact form of the validated structure.
    if _serialize_index(records) != raw:
        raise CorruptReceiptError("receipt index is not canonically encoded")
    return records


def _read_index(path: str) -> list[dict[str, str]]:
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return []
    return _parse_index(raw)


def _atomic_write(path: str, payload: bytes) -> None:
    tmp_path = path + ".tmp"
    with open(tmp_path, "wb") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    try:
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise
    fd = os.open(os.path.dirname(os.path.abspath(path)), os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def put(path: str, receipt: dict[str, str]) -> dict[str, str]:
    """Bind ``receipt``'s state and audit digests under its id in the index.

    A new id is added and the index is atomically replaced.  Putting the
    same id with identical state and audit digests is idempotent: a fresh
    dict is returned without touching the file bytes.  The same id with
    different digests raises :class:`ValueError` and leaves the file
    unchanged.  The returned dict always has the key order
    ``audit``, ``id``, ``state``.

    Type violations raise :class:`TypeError`; a bad key set, id or digest
    format raises :class:`ValueError`; a corrupt index raises
    :class:`CorruptReceiptError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    record = _validated_receipt(receipt)

    records = _read_index(path)
    for existing in records:
        if existing[ID] == record[ID]:
            if (
                existing[STATE] != record[STATE]
                or existing[AUDIT] != record[AUDIT]
            ):
                raise ValueError(
                    f"receipt id {record[ID]!r} is already bound to a "
                    "different state or audit record"
                )
            # Idempotent replay: brand-new copy, no filesystem change.
            return dict(record)

    records.append(record)
    records.sort(key=lambda entry: entry[ID])
    _atomic_write(path, _serialize_index(records))
    return dict(record)


def get(path: str, id: str) -> dict[str, str] | None:
    """Return a fresh copy of the receipt stored under ``id``, or None.

    A missing index file or an index without that id yields ``None``.
    Type violations raise :class:`TypeError`; a malformed ``id`` raises
    :class:`ValueError`; a corrupt index raises
    :class:`CorruptReceiptError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")
    if not isinstance(id, str):
        raise TypeError("id must be a str")
    if _ID_RE.fullmatch(id) is None:
        raise ValueError("id must match [A-Za-z0-9._-]{1,64}")

    for record in _read_index(path):
        if record[ID] == id:
            return dict(record)
    return None

        try:
            result = verify_chain_suffix(
                item[CHECKPOINT_ITEM_CHECKPOINT], item[DS_BATCH_SUCCESSORS],
                item[DS_BATCH_POLICIES], decision, policy, keyring,
                verify_moment,
            )
        except AuthenticationError as exc:
            reports.append(_decision_chain_item_report(
                item_id, _DS_VERIFY_UNAUTHENTICATED, str(exc), None
            ))
            results.append(None)
        except InvalidCheckpointError as exc:
            reports.append(_decision_chain_item_report(
                item_id, _DS_SUFFIX_INVALID_CHECKPOINT, str(exc), None
            ))
            results.append(None)
        except (InvalidChainError, TypeError, ValueError) as exc:
            # A TypeError here is a wrong field type inside a packet or
            # policy; the public argument types were validated up front.
            reports.append(_decision_chain_item_report(
                item_id, _DS_SUFFIX_INVALID_SUFFIX, str(exc), None
            ))
            results.append(None)
        else:
            reports.append(_decision_chain_item_report(
                item_id, _DS_VERIFY_VERIFIED, None, result
            ))
            results.append(result)

    # Fork detection: one predecessor digest pointing at two distinct
    # successor digests, ignoring items that did not verify.
    children: dict[str, set[str]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _suffix_edge_nodes(item)
        for upstream, downstream in zip(nodes, nodes[1:]):
            children.setdefault(upstream, set()).add(downstream)
    fork_edges = {
        upstream for upstream, digests in children.items()
        if len(digests) > 1
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _suffix_edge_nodes(item)
            if any(upstream in fork_edges for upstream in nodes[:-1]):
                report[STATUS] = _DS_CHAIN_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _DS_CHAIN_ERROR

    return {
        ITEMS: reports,
        VERSION: SUPERSEDE_VERSION,
    }


# --- Pruning of multi-round fork convergence archives -------------------------

CHAIN_PRUNE_VERSION = 1

PRUNE_PROJECT = "project"
PRUNE_CERTIFICATE = "certificate"
PRUNE_CHECKPOINT = "checkpoint"
PRUNE_ROUNDS = "rounds"
PRUNE_SOURCE = "source"
PRUNE_TARGET = "target"
PRUNE_DELETE = "delete"
PRUNE_RETAIN = "retain"
PRUNE_PLAN = "plan"
PRUNE_HEADER = "header"
PRUNE_PATH = "path"
PRUNE_MOMENT = "moment"
PRUNE_STATUS = "status"
PRUNE_BEFORE = "beforeDigest"
PRUNE_AFTER = "afterDigest"
PRUNE_ERROR = "error"
PRUNE_RECEIPT = "receipt"

PRUNE_STATUS_PRUNED = "pruned"
PRUNE_STATUS_DUPLICATE = "duplicate"

PRUNE_INTENT_PHASE = "phase"
PRUNE_INTENT_TARGET = "target"
PRUNE_INTENT_PLAN_DIGEST = "planDigest"
PRUNE_INTENT_CHECKPOINT_DIGEST = "checkpointDigest"
PRUNE_INTENT_CANDIDATE = INTENT_CANDIDATE
PRUNE_INTENT_PREDECESSOR = INTENT_PREDECESSOR
PRUNE_INTENT_NEW_DIGEST = INTENT_NEW_DIGEST
PRUNE_INTENT_OLD_DIGEST = INTENT_OLD_DIGEST

_PRUNE_ARCHIVE_KEYS = frozenset((
    PRUNE_CERTIFICATE,
    PRUNE_PROJECT,
    PRUNE_ROUNDS,
    VERSION,
))
_PRUNE_PRUNED_KEYS = frozenset((
    PRUNE_PROJECT,
    VERSION,
))
_PRUNE_ROUND_KEYS = frozenset((FC_CONFIRMATION, FC_SEQ))
_PRUNE_PLAN_PAYLOAD_KEYS = frozenset((
    PRUNE_CHECKPOINT,
    PRUNE_DELETE,
    PRUNE_RETAIN,
    PRUNE_SOURCE,
    PRUNE_TARGET,
    VERSION,
))
_PRUNE_HEADER_KEYS = frozenset((VD_ISSUER, KEY_VERSION, PRUNE_MOMENT))
_PRUNE_RECEIPT_PAYLOAD_KEYS = frozenset((
    PRUNE_AFTER,
    PRUNE_BEFORE,
    PRUNE_CHECKPOINT,
    PRUNE_DELETE,
    PRUNE_MOMENT,
    PRUNE_PLAN,
    PRUNE_RETAIN,
    PRUNE_STATUS,
    VERSION,
))
_PRUNE_ITEM_KEYS = frozenset((
    ID, PRUNE_PATH, PRUNE_PLAN, PRUNE_CHECKPOINT, PRUNE_HEADER,
))
_PRUNE_INTENT_KEYS = frozenset((
    PRUNE_INTENT_CANDIDATE,
    PRUNE_INTENT_CHECKPOINT_DIGEST,
    PRUNE_INTENT_NEW_DIGEST,
    PRUNE_INTENT_OLD_DIGEST,
    PRUNE_INTENT_PHASE,
    PRUNE_INTENT_PLAN_DIGEST,
    PRUNE_INTENT_PREDECESSOR,
    PRUNE_INTENT_TARGET,
    VERSION,
))

_PRUNE_HEX64 = re.compile(r"[0-9a-f]{64}\Z")


class InvalidPruneError(ValueError):
    """A chain prune archive, plan, receipt or intent breaks its contract."""


class InvalidPruneReceiptError(ValueError):
    """An offline prune receipt verification rejects the receipt."""


class StalePruneError(ValueError):
    """A prune target no longer matches the digest the plan was built from."""


def _prune_invalid(message: str) -> InvalidPruneError:
    return InvalidPruneError(f"invalid chain prune: {message}")


def _prune_stale(message: str) -> StalePruneError:
    return StalePruneError(f"stale chain prune: {message}")


def _prune_reject_duplicate_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate prune object keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _prune_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _prune_compact(obj: object, trailing_newline: bool = False) -> bytes:
    """Canonical compact sorted-key UTF-8 JSON, optionally with one trailing LF."""
    raw = json.dumps(
        obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    return raw + b"\n" if trailing_newline else raw


def _prune_is_digest(value: object) -> bool:
    return isinstance(value, str) and _PRUNE_HEX64.fullmatch(value) is not None


def _prune_hex_field(value: object, key: str) -> bytes:
    """Decode one archive byte field carried as non-empty lowercase hex."""
    if not isinstance(value, str):
        raise TypeError(f"{key} must be a hex str")
    try:
        return _hex_bytes(value)
    except ValueError as exc:
        raise _prune_invalid(
            f"{key} must be non-empty even-length lowercase hex"
        ) from exc


def _prune_pruned_bytes(project: str) -> bytes:
    """The trimmed archive installed after pruning: project marker only.

    The certificate and the whole ordered round group are pruned away;
    the project marker survives as one canonical version-1 JSON object
    ending in exactly one newline.  The marker carries no checkpoint:
    which checkpoint authorized the trim is a property of the signed
    plan and receipt, not of the retained bytes.
    """
    return _prune_compact(
        {
            PRUNE_PROJECT: project,
            VERSION: CHAIN_PRUNE_VERSION,
        },
        trailing_newline=True,
    )


def _prune_parse_archive(raw: bytes) -> dict:
    """Validate every byte of a version-1 convergence archive.

    The archive is one compact UTF-8 JSON object with recursively
    sorted keys, non-ASCII preserved and exactly one trailing newline,
    carrying exactly ``certificate``, ``project``, ``rounds`` and
    ``version`` (the integer 1).  ``project`` is a non-empty str; the
    certificate and the ordered rounds' confirmation bytes are
    non-empty lowercase hex, and the rounds are numbered
    consecutively from one with no gap, reordering or duplicate.  A
    :class:`bool` never poses as an int.  A non-bytes argument raises
    :class:`TypeError`; every encoding, key-set or field-shape fault
    raises :class:`InvalidPruneError`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("archive must be bytes")
    if not raw.endswith(b"\n") or raw.endswith(b"\n\n"):
        raise _prune_invalid(
            "archive must be a single JSON object ending in one LF"
        )
    try:
        text = raw[:-1].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _prune_invalid("archive is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_prune_reject_duplicate_keys
        )
    except json.JSONDecodeError as exc:
        raise _prune_invalid("archive is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("archive must be a JSON object")
    if set(data.keys()) != _PRUNE_ARCHIVE_KEYS:
        raise _prune_invalid(
            "archive must contain exactly the keys 'certificate', "
            "'project', 'rounds' and 'version'"
        )
    version = data[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("archive version must be an int")
    if version != CHAIN_PRUNE_VERSION:
        raise _prune_invalid("archive version must be the integer 1")
    project = data[PRUNE_PROJECT]
    if not isinstance(project, str):
        raise TypeError("archive project must be a str")
    if project == "":
        raise _prune_invalid("archive project must be non-empty")
    certificate = _prune_hex_field(
        data[PRUNE_CERTIFICATE], "archive certificate"
    )
    rounds_raw = data[PRUNE_ROUNDS]
    if not isinstance(rounds_raw, list):
        raise TypeError("archive rounds must be a list")
    if not rounds_raw:
        raise _prune_invalid("archive rounds must be non-empty")
    rounds: list[dict] = []
    for position, entry in enumerate(rounds_raw):
        where = f"archive round {position}"
        if not isinstance(entry, dict):
            raise TypeError(f"{where} must be an object")
        if set(entry.keys()) != _PRUNE_ROUND_KEYS:
            raise _prune_invalid(
                f"{where} must contain exactly the keys 'confirmation' "
                "and 'seq'"
            )
        seq = entry[FC_SEQ]
        if isinstance(seq, bool) or not isinstance(seq, int):
            raise TypeError(f"{where} seq must be an int")
        if seq != position + 1:
            raise _prune_invalid(
                f"{where} seq must be {position + 1}: rounds are numbered "
                "consecutively from one with no gap, reordering or duplicate"
            )
        confirmation = _prune_hex_field(
            entry[FC_CONFIRMATION], f"{where} confirmation"
        )
        rounds.append({FC_SEQ: seq, FC_CONFIRMATION: confirmation})
    if _prune_compact(data, trailing_newline=True) != raw:
        raise _prune_invalid(
            "archive encoding is not the canonical compact form"
        )
    return {
        PRUNE_PROJECT: project,
        PRUNE_CERTIFICATE: certificate,
        PRUNE_ROUNDS: rounds,
    }


def _prune_parse_pruned(raw: bytes, project: str) -> None:
    """Validate an already-trimmed project marker archive.

    The marker carries exactly ``project`` and ``version``; which
    checkpoint authorized the trim is a property of the signed plan
    and receipt, so the marker alone authenticates nothing.  Every
    encoding, key-set or binding fault raises
    :class:`InvalidPruneError`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("archive must be bytes")
    if not raw.endswith(b"\n") or raw.endswith(b"\n\n"):
        raise _prune_invalid(
            "pruned archive must be a JSON object ending in one LF"
        )
    try:
        text = raw[:-1].decode("utf-8")
        data = json.loads(
            text, object_pairs_hook=_prune_reject_duplicate_keys
        )
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise _prune_invalid("pruned archive is not valid JSON") from exc
    if not isinstance(data, dict) or set(data.keys()) != _PRUNE_PRUNED_KEYS:
        raise _prune_invalid("pruned archive has an illegal key set")
    version = data[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("pruned archive version must be an int")
    if version != CHAIN_PRUNE_VERSION:
        raise _prune_invalid("pruned archive version must be the integer 1")
    if data[PRUNE_PROJECT] != project:
        raise _prune_invalid("pruned archive is bound to another project")
    if _prune_compact(data, trailing_newline=True) != raw:
        raise _prune_invalid(
            "pruned archive encoding is not the canonical compact form"
        )


