def test_argument_taxonomy(self):
    good = [self.packet("a", self.att_a)]

    def adjudicate(**kwargs):
        kwargs.setdefault("items", good)
        kwargs.setdefault("policy", self.policy)
        kwargs.setdefault("keyring", self.ring)
        kwargs.setdefault("moment", self.moment)
        kwargs.setdefault("issuer", JUDGE)
        kwargs.setdefault("version", 1)
        return adjudicate_prune_attestations(**kwargs)

    self.assertRaises(TypeError, adjudicate(items=(good[0],)))
    self.assertRaises(TypeError, adjudicate(items=["x"]))
    self.assertRaises(TypeError, adjudicate(items=[
        {"id": 1, "attestation": self.att_a}
    ]))
    self.assertRaises(TypeError, adjudicate(items=[
        {"id": "x", "attestation": "raw"}
    ]))
    self.assertRaises(ValueError, adjudicate(items=[]))
    self.assertRaises(ValueError, adjudicate(items=[
        self.packet("", self.att_a)
    ]))
    self.assertRaises(ValueError, adjudicate(items=[
        self.packet("dup", self.att_a), self.packet("dup", self.att_a),
    ]))
    self.assertRaises(ValueError, adjudicate(items=[
        {"id": "x"}
    ]))
    self.assertRaises(TypeError, adjudicate(policy=[]))
    self.assertRaises(ValueError, adjudicate(policy={
        "batch": BATCH, "sites": {SITE_A: {1}}, "threshold": 2,
    }))
    self.assertRaises(ValueError, adjudicate(policy={
        "batch": BATCH,
        "sites": {SITE_A: {0}},
        "threshold": 1,
    }))
    self.assertRaises(TypeError, adjudicate(policy={
        "batch": BATCH,
        "sites": {SITE_A: [1]},
        "threshold": 1,
    }))
    self.assertRaises(TypeError, adjudicate(moment=True))
    self.assertRaises(ValueError, adjudicate(moment=-1))
    self.assertRaises(TypeError, adjudicate(issuer=5))
    self.assertRaises(ValueError, adjudicate(issuer=""))
    self.assertRaises(TypeError, adjudicate(version=True))
    self.assertRaises(ValueError, adjudicate(version=-2))
    # Unknown adjudicator credentials.
    self.assertRaises(
        AuthenticationError, adjudicate(issuer="ghost")
    )

